insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.generic.reasons[0].cites[0].quote', 'Odam farzandining barcha amallari oʻzi uchundir, roʻza bundan mustasno; u Men uchundir, unga mukofotni Men beraman.');
