insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.obligatory.reasons[0].cites[1].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.obligatory.reasons[0].cites[1].references[0].hadith', '38');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.obligatory.reasons[0].cites[0].quote', 'Islom besh ustun ustiga qurilgan: Allohdan oʻzga ibodatga loyiq iloh yoʻqligiga va Muhammad Allohning Rasuli ekanligiga shohadat berish, namozni toʻkis ado etish, zakot berish, Haj qilish va Ramazon roʻzasini tutish.');
