insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[1].cites[0].quote', 'Tashriq kunlari yeyish va ichish kunlaridir.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[1].cites[0].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[1].cites[0].references[0].hadith', '1141a');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[1].id', 'fasting-reason-tashriq');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[1].title', 'Tashriq kunlari');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].intro', 'Abu Ubayd (r.a.) rivoyat qiladi:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].quote', 'Men Umar (r.a.) bilan hayit namozida ishtirok etdim. U xutbadan oldin namoz oʻqidi, soʻngra dedi: Allohning Rasuli (s.a.v.) bu ikki kunda roʻza tutishni taqiqlaganlar. Qurbon hayiti kuni qurbonlik hayvonlaringizning goʻshtini yeysizlar, Fitriy hayit kuni esa roʻzangizni ochasizlar.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].references[1].collection', 'ibnmajah');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].references[1].hadith', '1722');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[0].cites[1].references[0].hadith', '2416');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].intro', 'Abu Hurayra (r.a.) rivoyat qiladi:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].quote', 'Ikki kunda roʻza tutish taqiqlangan: Fitriy hayit kuni va Qurbon hayiti kuni.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].references[1].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.prohibiting.reasons[0].cites[0].references[1].hadith', '1138');
