insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.ics-title', 'Nafl (tatavvuʼ) roʻza sababi');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[1].cites[0].intro', 'Abu Qatoda (r.a.) Allohning Rasuli Muhammad (s.a.v.) shunday deganlarini rivoyat qiladi:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[1].cites[0].quote', 'Men Allohdan umid qilamanki, Arafah kunidagi roʻza oʻtgan va kelgusi yil gunohlariga kafforat boʻladi; Ashuro kunidagi roʻza esa oʻtgan yil gunohlariga kafforat boʻladi.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[1].cites[0].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[1].cites[0].references[0].hadith', '1162');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[1].headlines.arafah', 'Arafah kuni');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[1].headlines.ashura', 'Ashuro kuni');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[1].id', 'fasting-reason-arafah-or-ashura');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[1].title', 'Arafah va Ashuro kunlari');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[2].cites[0].intro', 'Paygʻambar Muhammad (s.a.v.)ning ayollaridan biri (r.a.) shunday deganlar:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[2].cites[0].quote', 'Allohning Rasuli Muhammad (s.a.v.) Zul-hijja oyining dastlabki toʻqqiz kunida, Ashuro kunida va har oyda uch kun roʻza tutar edilar…');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[1].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[1].hadith', '2417');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[2].cites[0].references[0].hadith', '2437');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[2].id', 'fasting-reason-first-9-dhu-al-hijjah');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[2].title', 'Zul-hijja oyining dastlabki toʻqqiz kuni');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[1].intro', 'Abdulloh ibn Amr ibn al-Os (r.a.) rivoyat qiladi:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[1].quote', 'Oyiga uch kun roʻza tutish kifoya qiladi; chunki yaxshilik uchun oʻn barobar savob beriladi, shu sababli bu butun yil roʻzasiga oʻxshaydi.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[1].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[1].references[0].hadith', '1975');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[2].intro', 'Abu Qatoda (r.a.) Allohning Rasuli (s.a.v.) shunday deganlarini rivoyat qiladi:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[2].quote', 'Har oyda uch kun roʻza tutish va har yili Ramazon roʻzasi tutish — doimiy roʻzadir.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[2].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[2].references[0].hadith', '1162');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[3].intro', 'Allohning Rasuli Abu Zarr (r.a.)ga shunday deganlar:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[3].quote', 'Har oyda uch kun roʻza tutish butun umr roʻza tutgandekdir.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[3].references[0].collection', 'ibnmajah');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[3].references[0].hadith', '1708');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[4].intro', 'Jarir ibn Abdulloh (r.a.)dan rivoyat qilinganki, Paygʻambar (s.a.v.) shunday deganlar:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[4].quote', 'Har oyda uch kun roʻza tutish butun umr roʻza tutgandekdir; bu yorqin kunlar — oyning oʻn uchinchi, oʻn toʻrtinchi va oʻn beshinchi kunlaridir.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[4].references[0].hadith', '2420');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[5].intro', 'Abu Hurayra (r.a.) rivoyat qiladi:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[5].quote', 'Mening yaqin doʻstim (Paygʻambar Muhammad (s.a.v.)) menga uch amalni vasayat qildilar: har oyda uch kun roʻza tutishni, Duha namozidan ikki rakʼat oʻqishni va uxlashdan oldin Vitir namozini oʻqishni.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].collection', 'bukhari');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[5].references[0].hadith', '1981');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[6].intro', 'Abu Dardo (r.a.) rivoyat qiladi:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[6].quote', 'Mening doʻstim (Paygʻambar (s.a.v.)) menga uch amalni vasayat qildilar, men ularni hech qachon tark etmayman; menga har oyda uch kun roʻza tutishni buyurdilar.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].collection', 'abudawud');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[6].references[0].hadith', '1433');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[0].intro', 'Paygʻambar Muhammad (s.a.v.) Abu Zarr (r.a.)ga shunday nasihat qilganlar:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[0].quote', 'Agar oyning bir qismida roʻza tutsangiz, oʻn uchinchi, oʻn toʻrtinchi va oʻn beshinchi kunlarni tuting.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].collection', 'tirmidhi');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].cites[0].references[0].hadith', '761');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].id', 'fasting-reason-white-days');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[3].title', 'Oq kunlar');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[4].cites[1].intro', 'Usoma ibn Zayd (r.a.) Allohning Rasuli (s.a.v.) shunday deganlarini rivoyat qiladi:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[4].cites[1].quote', 'Bu ikki kun — amallar Olamlar Rabbiga arz qilinadigan kunlardir; men amallarim roʻza holatimda arz qilinishini yaxshi koʻraman.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].collection', 'nasai');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[4].cites[1].references[0].hadith', '2358');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[4].cites[2].intro', 'Abu Qatoda al-Ansoriy (r.a.) Paygʻambardan (s.a.v.) dushanba kuni roʻza tutish haqida soʻradi, U zot shunday dedilar:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[4].cites[2].quote', 'Bu men tugʻilgan kun, menga paygʻambarlik berilgan yoki vahiy nozil qilingan kundir.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[4].cites[2].references[0].collection', 'muslim');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[4].cites[2].references[0].hadith', '1162b');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[4].cites[3].intro', 'Oisha (r.a.) rivoyat qiladi:');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[4].cites[3].quote', 'Paygʻambar (s.a.v.) dushanba va payshanba kunlari roʻza tutishga alohida eʼtibor berar edilar.');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[4].cites[3].references[0].collection', 'tirmidhi');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[4].cites[3].references[0].hadith', '745');
insert into i18n_bundles (locale, code, value) values ('uz', 'fasting.reason-groups.voluntary.reasons[4].cites[0].intro', 'Bu soʻz Abu Hurayra (r.a.) tomonidan rivoyat qilingan:');
